from typing import List

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)

        for d in range(-(n - 1), n):
            cells = []
            for i in range(max(0, d), min(n, n + d)):
                j = i - d
                cells.append((i, j))

            values = [grid[i][j] for i, j in cells]

            if d >= 0:
                values.sort(reverse=True)
            else:
                values.sort()

            for (i, j), value in zip(cells, values):
                grid[i][j] = value

        return grid

from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        max_group = max(groups)
        answer_by_value = [-1] * (max_group + 1)
        seen = [False] * (max_group + 1)

        for index, value in enumerate(elements):
            if value <= max_group and not seen[value]:
                seen[value] = True
                for multiple in range(value, max_group + 1, value):
                    if answer_by_value[multiple] == -1:
                        answer_by_value[multiple] = index

        return [answer_by_value[group] for group in groups]

